  return specialDocument({title,description,path,schema,body:`<main>${breadcrumbs(crumbs)}<header class="service-hero"><div class="wrap service-hero-grid"><div><span class="eyebrow">The people behind the service</span><h1>Meet our housing disrepair team</h1><p class="service-lead">Housing Condition Claims UK is delivered by Sheldon Davidson Solicitors Limited. Our housing team combines senior firm leadership, legal oversight, pre-action experience, evidence gathering and clear client communication.</p><div class="service-actions"><a class="btn" href="/#callback">Speak to the team →</a></div></div><aside class="service-check"><strong>A regulated legal team</strong><p>The firm is authorised and regulated by the Solicitors Regulation Authority under SRA number 519502.</p></aside></div></header><section class="team-section"><div class="wrap"><span class="eyebrow">Leadership and housing specialists</span><h2 class="section-title">Experienced, approachable support</h2><p class="section-intro">Meet all ${team.length} people leading and delivering the service. Select any person to read their full profile.</p><div class="team-grid" aria-label="Housing service team profiles">${cards}</div></div></section><section class="service-section wrap"><div class="service-split"><div><span class="eyebrow">How we work</span><h2>Clear responsibility at every stage.</h2><p>Claims are built around the repair history, landlord responsibility, supporting evidence and the real effect of the conditions. The team explains what is needed, keeps clients updated and avoids promises that the evidence cannot support.</p></div><ul class="service-list"><li>Initial eligibility and evidence review</li><li>Repair chronology and formal notice</li><li>Surveyor and expert coordination where appropriate</li><li>Negotiation, litigation support and client updates</li></ul></div></section><section class="service-final wrap"><div><span class="eyebrow">Start with the facts</span><h2>Tell the team what is wrong with your home.</h2><p>Share when you first reported it, what action followed and how the household has been affected.</p></div><a class="btn" href="/#callback">Request a callback →</a></section></main>`});
