const renderComplaintsPage = () => {
  const path = "/about-us/complaints/";
  const title = "Complaints Procedure | Housing Condition Claims UK";
  const description = "How to raise a complaint with Sheldon Davidson Solicitors Limited, the investigation timetable and independent escalation routes.";
  const crumbs = [{path:"/",label:"Home"},{path:"/about-us/",label:"About us"},{path,label:"Complaints"}];
  const schema = {"@context":"https://schema.org","@graph":[{"@type":"WebPage","name":title,"url":absoluteUrl(path),"description":description,"about":{"@type":"LegalService","name":"Sheldon Davidson Solicitors Limited","identifier":"SRA 519502"}},breadcrumbSchema(crumbs)]};
  return specialDocument({title,description,path,schema,body:`<main>${breadcrumbs(crumbs)}<header class="service-hero"><div class="wrap service-hero-grid"><div><span class="eyebrow">Client care</span><h1>Our complaints procedure</h1><p class="service-lead">We want to provide a professional, clear service. If you are unhappy with any aspect of our work, please tell us so the concern can be investigated and, where possible, resolved.</p></div><aside class="service-check"><strong>Start with the person handling your matter</strong><p>They may be able to resolve the issue quickly. If you prefer not to contact them, you can contact our Managing Partner directly.</p></aside></div></header><section class="service-section wrap"><div class="service-split"><div><span class="eyebrow">How to complain</span><h2>Contact Victoria McCormack</h2><p>Victoria McCormack, Managing Partner, oversees the formal complaints process. Include your name, file reference where available, what has gone wrong and the outcome you would like us to consider.</p><div class="contact-panel"><p><strong>Email</strong><br><a href="mailto:complaints@sds-solicitors.com">complaints@sds-solicitors.com</a></p><p><strong>Telephone</strong><br><a href="tel:01617963000">0161 796 3000</a></p><p><strong>Post</strong><br>Sheldon Davidson Solicitors Limited<br>219 Bury New Road<br>Whitefield, Manchester<br>M45 8GW</p></div></div><div class="comp-card"><strong>There is no charge for investigating your complaint.</strong><p>We will handle it promptly and fairly. The firm’s internal process should normally be completed within eight weeks.</p></div></div></section><section class="service-band"><div class="wrap"><span class="eyebrow">Formal process</span><h2 class="section-title">What happens after we receive it</h2><ol class="complaints-steps"><li><strong>Acknowledgement</strong><span>We aim to acknowledge the complaint within two working days and provide a copy of the procedure.</span></li><li><strong>Investigation</strong><span>Victoria will review the file, speak with the relevant staff and, where appropriate, consult senior management.</span></li><li><strong>Meeting option</strong><span>We aim to invite you to discuss the complaint within 14 days of acknowledgement. If a meeting takes place, we will write within three days to confirm the discussion and any agreed solution.</span></li><li><strong>Written response</strong><span>If a meeting is not appropriate or is not wanted, we aim to send a detailed written response within 21 days of acknowledgement.</span></li><li><strong>Review</strong><span>If you remain dissatisfied, you can ask Sheldon Davidson, Managing Director, to review the response. We aim to confirm the final position within 14 days of that request.</span></li></ol></div></section><section class="service-section wrap"><div class="service-split"><div><span class="eyebrow">Independent review</span><h2>The Legal Ombudsman</h2><p>If we have not resolved your complaint within eight weeks, or you are dissatisfied with our final response, you may be able to ask the Legal Ombudsman to review the service complaint.</p><p>Complaints to the Legal Ombudsman generally need to be made within one year of the act or omission complained about, or within one year of when you should reasonably have known there was cause for complaint. You must also normally contact the Ombudsman within six months of our final response.</p><p><a class="service-text-link" href="https://www.legalombudsman.org.uk/" rel="noopener">Visit the Legal Ombudsman website →</a></p></div><div class="contact-panel"><p><strong>Telephone</strong><br><a href="tel:03005550333">0300 555 0333</a></p><p><strong>Email</strong><br><a href="mailto:enquiries@legalombudsman.org.uk">enquiries@legalombudsman.org.uk</a></p><p><strong>Post</strong><br>Legal Ombudsman<br>PO Box 6167<br>Slough<br>SL1 0EH</p></div></div></section><section class="service-section service-process"><div class="wrap"><span class="eyebrow">Conduct concerns</span><h2>When to contact the SRA</h2><p class="section-intro">The Legal Ombudsman deals with service complaints. The Solicitors Regulation Authority may investigate serious professional conduct concerns, such as dishonesty or breaches of its rules. It does not normally resolve complaints about poor service or legal fees.</p><a class="service-text-link" href="https://www.sra.org.uk/consumers/problems/report-solicitor/" rel="noopener">Read the SRA’s reporting guidance →</a></div></section></main>`});
};

