  const card = (article, featuredCard = false) => `<article class="news-card${featuredCard ? " news-card-featured" : ""}"><div class="news-card-meta"><span>Housing disrepair</span><time datetime="${esc(article.date)}">${esc(formatArticleDate(article.date))}</time></div><h2><a href="${newsPath(article)}">${esc(article.title)}</a></h2><p>${esc(article.summary)}</p><a class="news-read" href="${newsPath(article)}" aria-label="Read ${esc(article.title)}">Read article →</a></article>`;
  return specialDocument({title,description,path,schema,body:`<main>${breadcrumbs(crumbs)}<header class="service-hero news-index-hero"><div class="wrap service-hero-grid"><div><span class="eyebrow">Housing news and practical guidance</span><h1>Clear updates for people living in rented homes.</h1><p class="service-lead">Housing-law changes can be difficult to follow when you are also dealing with damp, heating failure, unsafe electrics or repeated repair delays. Our articles explain the practical points and the evidence worth keeping.</p></div><aside class="service-check"><strong>Written for tenants</strong><p>Every article is general information, not individual legal advice. Publication dates are shown so you can judge context and check later developments.</p><a href="/#callback">Ask for an individual assessment →</a></aside></div></header><section class="news-section wrap"><div class="news-heading"><div><span class="eyebrow">Latest article</span><h2 class="section-title">What tenants need to know now</h2></div><p>Substantive, rewritten articles based on the current Sheldon Davidson Solicitors housing-news archive.</p></div>${card(featured,true)}<div class="news-grid">${remaining.map((article)=>card(article)).join("")}</div></section><section class="service-band news-principles"><div class="wrap service-copy-grid"><article><span class="eyebrow">Use the date</span><h2>Law and policy can move quickly.</h2><p>Read each update in its publication context. Current regulations, official guidance and the precise terms of a tenancy should be checked before action is taken.</p></article><article class="service-council-card"><span class="service-label">Need advice?</span><h2>Your repair history is individual.</h2><p>Tell the team what went wrong, when the landlord was notified, what response followed and how the conditions affected the household.</p><a href="/#callback">Request a callback →</a></article></div></section></main>`});
