  const readMinutes = Math.max(4, Math.ceil(wordCount / 210));
  const schema = {"@context":"https://schema.org","@graph":[{"@type":"NewsArticle","headline":article.title,"description":article.summary,"datePublished":article.date,"dateModified":"2026-09-23","mainEntityOfPage":absoluteUrl(path),"url":absoluteUrl(path),"isBasedOn":article.sourceUrl,"author":{"@type":"Organization","name":"Sheldon Davidson Solicitors Limited","url":"https://www.sds-solicitors.com/"},"publisher":{"@type":"Organization","name":"Housing Condition Claims UK","parentOrganization":{"@type":"LegalService","name":"Sheldon Davidson Solicitors Limited","identifier":"SRA 519502"}}},{"@type":"WebPage","name":title,"url":absoluteUrl(path)},breadcrumbSchema(crumbs)]};
