  const relatedCards = relatedNews.map((item) => `<article class="news-mini"><time datetime="${esc(item.date)}">${esc(formatArticleDate(item.date))}</time><h3><a href="${newsPath(item)}">${esc(item.title)}</a></h3><a href="${newsPath(item)}">Read article →</a></article>`).join("");
  return specialDocument({title,description,path,type:"article",schema,body:`<main>${breadcrumbs(crumbs)}<article class="news-article"><header class="service-hero news-article-hero"><div class="wrap news-hero-copy"><span class="eyebrow">Housing disrepair news</span><h1>${esc(article.title)}</h1><p class="service-lead">${esc(article.summary)}</p><div class="news-byline"><time datetime="${esc(article.date)}">Published ${esc(formatArticleDate(article.date))}</time><span>${readMinutes} minute read</span><span>By Sheldon Davidson Solicitors</span></div></div></header><div class="wrap news-layout"><aside class="news-summary"><span class="service-label">Key points</span><ul>${article.takeaways.map((point)=>`<li>${esc(point)}</li>`).join("")}</ul><a href="/#callback">Discuss your housing conditions →</a></aside><div class="news-prose"><p class="news-intro">${esc(article.intro)}</p>${article.sections.map((section)=>`<section><h2>${esc(section.heading)}</h2>${section.paragraphs.map((paragraph)=>`<p>${esc(paragraph)}</p>`).join("")}</section>`).join("")}<aside class="news-source-note"><strong>Publication context</strong><p>This is a rewritten presentation of a Sheldon Davidson Solicitors housing update, adapted for Housing Condition Claims UK. It is general information and not a substitute for advice on your tenancy or claim.</p><a href="${esc(article.sourceUrl)}" target="_blank" rel="noopener noreferrer">View the original SDS publication →</a></aside></div></div><section class="service-related wrap news-guidance"><span class="eyebrow">Related housing guidance</span><h2>Continue reading</h2><div>${relatedGuidance}</div></section><section class="news-more"><div class="wrap"><span class="eyebrow">More from the team</span><h2 class="section-title">Related news and explainers</h2><div class="news-mini-grid">${relatedCards}</div><a class="service-text-link" href="/about-us/news/">View all news →</a></div></section><section class="service-final wrap"><div><span class="eyebrow">Your circumstances matter</span><h2>Has your landlord failed to deal with a reported repair?</h2><p>Share the condition, reporting history and current impact. The team can explain whether it may be able to help.</p></div><a class="btn" href="/#callback">Request a callback →</a></section></article></main>`});
