  if (path.includes("/news/")) return "SDS legal update";
  if (path.includes("/our-people/")) return "Our legal team";
  if (path.startsWith("/housing-disrepair")) return "Housing condition claims";
  if (path.startsWith("/about-us")) return "About Sheldon Davidson Solicitors";
  if (path.startsWith("/contact-us")) return "Contact SDS";
